#include <iostream>
using namespace std;
int main() {
    int n, a[50] = {0}, ans = 0;
    cin >> n;
    for(int i = 1; i <= n; i++) {
        int t = i, pos = 0;
        while(t) {
            a[pos++] = t % 2;
            t /= 2;
        }
        bool ok = true;
        for(int i = 0; i < pos; i++)
            if(a[i] != a[pos - i - 1]) {
                ok = false;
                break;
            }
        ans += ok;
    }
    cout << ans;
    return 0;
}

